('10000000-0000-4000-8000-000000000004', 'Gucci', 'Lujo italiano con diseño vanguardista.', 'https://images.pexels.com/photos/1573236/pexels-photo-1573236.jpeg?auto=compress&cs=tinysrgb&w=600', FALSE),
